// src/mocks/worldbook-test.ts
function mockWorldBookTest(data2, sampleText, scanDepth = 4) {
  void scanDepth;
  const text = sampleText.toLowerCase();
  const hits = data2.entries.map((entry) => {
    const base = {
      entry_id: entry.id ?? entry.comment,
      comment: entry.comment || entry.keys.join(" / ") || "\uFF08\u672A\u547D\u540D\u6761\u76EE\uFF09",
      token_count: entry.token_count ?? Math.ceil(entry.content.length / 1.6)
    };
    if (!entry.enabled) {
      return {
        ...base,
        matched: false,
        match_type: "none",
        matched_key: null,
        in_budget: false,
        final_position: null
      };
    }
    if (entry.constant) {
      return {
        ...base,
        matched: true,
        match_type: "constant",
        matched_key: null,
        in_budget: true,
        final_position: entry.position
      };
    }
    const hitKey = entry.keys.find((k) => text.includes(k.toLowerCase())) ?? null;
    const secondaryOk = !entry.selective || entry.secondary_keys.some((k) => text.includes(k.toLowerCase()));
    if (!hitKey || !secondaryOk) {
      return {
        ...base,
        matched: false,
        match_type: "none",
        matched_key: null,
        in_budget: false,
        final_position: null
      };
    }
    return {
      ...base,
      matched: true,
      match_type: entry.use_regex ? "regex" : "keyword",
      matched_key: hitKey,
      in_budget: true,
      final_position: entry.position
    };
  });
  const budget = data2.token_budget;
  let used = 0;
  const ordered = data2.entries.map((e, i) => ({ e, i })).filter(({ i }) => hits[i].matched).sort((a, b) => b.e.priority - a.e.priority);
  for (const { i } of ordered) {
    const cost = hits[i].token_count;
    if (used + cost <= budget) {
      used += cost;
    } else {
      hits[i] = { ...hits[i], in_budget: false, final_position: null };
    }
  }
  return { entries: hits, total_tokens: used, token_budget: budget };
}

